mapper.select:
SELECT
FROM parts WHERE id IN
#{id}

select p.id, part_name, part_code, standard_id, `is`.part_type AS partType, standard_parameters, parameters AS partParameters,
       is_qualified AS qualifiedFlag, inspection_time, inspection_details, inspection_suggestion,
       p.inspection_flag, p.create_time, p.update_time
from parts p
left join inspection_standards as `is` on p.standard_id = is.id


        and p.part_name like concat('%', #{query.partName}, '%')


        and p.inspection_flag = #{query.inspectionFlag}


        and p.is_qualified = #{query.isQualified}


        and p.inspection_time BETWEEN #{query.inspectionStartTime} AND #{query.inspectionEndTime}


        and p.is_qualified = #{query.isQualified}

    AND p.delete_flag = 0

ORDER BY p.inspection_time desc, id asc
